<section class="theme-picker" aria-labelledby="theme-picker-title">
    <h2 id="theme-picker-title"><i class="fas fa-palette" aria-hidden="true"></i> Personalize your view</h2>
    <p>Choose a background color for this browser. Your preference is saved automatically.</p>
    <div class="swatch-container" role="group" aria-label="Background color choices">
        <button class="swatch" type="button" style="background:#ffffff" data-theme-color="white" aria-label="White"></button>
        <button class="swatch" type="button" style="background:#a8dadc" data-theme-color="#a8dadc" aria-label="Polar ice"></button>
        <button class="swatch" type="button" style="background:#2a9d8f" data-theme-color="#2a9d8f" aria-label="Forest green"></button>
        <button class="swatch" type="button" style="background:#f4d35e" data-theme-color="#f4d35e" aria-label="Solar gold"></button>
        <button class="swatch" type="button" style="background:#e63946" data-theme-color="#e63946" aria-label="Wildfire red"></button>
        <button class="swatch" type="button" style="background:#5e548e" data-theme-color="#5e548e" aria-label="Midnight violet"></button>
        <button class="swatch" type="button" style="background:#d8f3dc" data-theme-color="#d8f3dc" aria-label="Wind whisper"></button>
        <button class="swatch" type="button" style="background:linear-gradient(135deg,#fff 45%,#123d35 45% 55%,#fff 55%)" data-theme-color="" aria-label="Reset background color"></button>
    </div>
</section>
